    while (i < bb.limit()) {
        byte b = bb.get(i);
        if (b >= 0) {
            // ASCII character
            sb.append((char) b);
            i++;
        } else {
            // Multi-byte UTF-8 character
            int numBytes = 0;
            int continuationByteMask = 0x80;
            int continuationBitCount = 0;

            // Determine the number of bytes in the multi-byte character
            while ((b & continuationByteMask) != 0) {
                numBytes++;
                continuationByteMask >>= 1;
                continuationBitCount++;
                if (continuationBitCount > 5) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
            }

            // Ensure there are enough bytes in the buffer
            if (i + numBytes > bb.limit()) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }

            // Read the continuation bytes
            int codePoint = (b & ((1 << (7 - continuationBitCount)) - 1)) << (6 * numBytes);
            for (int j = 0; j < numBytes - 1; j++) {
                b = bb.get(++i);
                if ((b & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence");
                }
                codePoint |= (b & 0x3F) << (6 * (numBytes - 2 - j));
            }

            // Append the character to the StringBuilder
            sb.appendCodePoint(codePoint);
            i += numBytes;
        }
    }

