    try {
        if (file.isDirectory()) {
            File[] files = file.listFiles();
            if (files != null) {
                for (File f : files) {
                    forceDeleteOnExit(f);
                }
            }
        }
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                if (file.delete()) {
                    System.out.println("File or directory deleted successfully: " + file.getAbsolutePath());
                } else {
                    throw new IOException("Failed to delete file or directory: " + file.getAbsolutePath());
                }
            } catch (SecurityException e) {
                throw new IOException("Security exception while deleting file or directory: " + file.getAbsolutePath(), e);
            }
        }));
