public class LogHandler {
    private final LinkedBlockingQueue<LogRecord> logQueue = new LinkedBlockingQueue<>();

    public void addMessage(final LogRecord lr) {
        if (lr == null) {
            throw new IllegalArgumentException("LogRecord cannot be null");
        }
        try {
            SwingUtilities.invokeLater(() -> {
                logQueue.add(lr);
                processLogQueue();
            });
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void processLogQueue() {
        while (!logQueue.isEmpty()) {
            LogRecord lr = logQueue.poll();
            if (lr != null) {
                // Code to display the log record in the LogTable
                System.out.println("Adding log message: " + lr.getMessage());
            }
        }
    }
}
