public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if target graph and resultMap are not null
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and result map cannot be null");
    }

    // Clear the target graph to ensure it is empty
    target.removeAllVertices();
    target.removeAllEdges();

    // Get the set of vertices from the resultMap
    Set<String> vertexKeys = resultMap.keySet();
    if (vertexKeys.isEmpty()) {
        throw new IllegalArgumentException("Result map is empty");
    }

    // Split the vertex keys into two sets for the two parts of the bipartite graph
    Set<String> partA = new HashSet<>(vertexKeys);
    Set<String> partB = new HashSet<>();

    // Remove one vertex from partA and add it to partB to ensure they are not empty
    if (!partA.isEmpty()) {
        partB.add(partA.iterator().next());
        partA.remove(partB.iterator().next());
    } else {
        throw new IllegalArgumentException("Result map has less than 2 vertices");
    }

    // Add vertices to the target graph
    for (String key : vertexKeys) {
        V vertex = resultMap.get(key);
        target.addVertex(vertex);
    }

    // Generate edges between vertices in partA and partB
    for (String vertexA : partA) {
        for (String vertexB : partB) {
            E edge = target.getDefaultEdge();
            target.addEdge(resultMap.get(vertexA), resultMap.get(vertexB), edge);
        }
    }
}
