public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    byte[] messageBytes = schema.toByteArray(message);
    int messageLength = messageBytes.length;

    // Write the message length as a varint
    buffer = VarInts.writeUnsignedLong(buffer, messageLength);

    // Check if the combined length fits in the buffer
    if (buffer.length < messageLength + buffer.offset) {
        throw new BufferOverflowException("Buffer is too small");
    }

    // Add the message bytes to the buffer
    System.arraycopy(messageBytes, 0, buffer.buffer, buffer.offset, messageLength);
    buffer.offset += messageLength;

    // If the buffer is full, write the buffer to the output stream
    if (buffer.offset == buffer.buffer.length) {
        out.write(buffer.buffer);
        buffer.offset = 0;
    }

    return messageLength;
}
