public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || schema == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    try {
        // Serialize the message
        byte[] messageBytes = schema.toBytes(message);

        // Get the length of the message
        int messageSize = messageBytes.length;

        // Write the length of the message as a varint
        int bytesWritten = CodedOutputStream.computeRawVarint32Size(messageSize);
        if (buffer.spaceLeft() < bytesWritten) {
            buffer = buffer.grow(bytesWritten);
        }
        CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
        codedOut.writeRawVarint32(messageSize);

        // Write the message itself
        if (buffer.spaceLeft() < messageSize) {
            buffer = buffer.grow(messageSize);
        }
        byte[] bufferArray = buffer.buffer();
        System.arraycopy(messageBytes, 0, bufferArray, buffer.pos(), messageSize);
        buffer = buffer.accumulate(messageSize);

        // Write thebuf ot the OutputStream
        out.write(bufferArray, 0, buffer.pos());
        out.flush();

        return messageSize;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error writing to OutputStream", e);
    }
}
