        throw new IllegalArgumentException("Start and end times cannot be negative.");
    }

    while (start < end) {
        long lowerBound = start;
        long upperBound = Math.min(start + FETCH_DATA_DURATION, end);

        timeRanges.add(new TimeRange(lowerBound, upperBound));

