    final long FETCH_DATA_DURATION = 24 * 60 * 60 * 1000; // 24 hours in milliseconds

    if (start >= end) {
        throw new IllegalArgumentException("Start time must be before end time");
    }

    while (start < end) {
        long currentEnd = start + FETCH_DATA_DURATION;
        if (currentEnd > end) {
            currentEnd = end;
        }
        timeRanges.add(new TimeRange(start, currentEnd));
        start = currentEnd;
    }

    return timeRanges;
}

