        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else if (c <= 0x10FFFF) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid Unicode character");
        }
    }
    return size;
}
