        int utf8Length = UTF8.charAt(str, 0);
        if (utf8Length == 0) {
            utf8Length = str.length();
        }

        // Check if the LinkedBuffer has sufficient space
        if (lb.getHead() + utf8Length > lb.getCapacity()) {
            // Initialize a new LinkedBuffer with double the capacity
            lb = new LinkedBuffer(lb.getCapacity() * 2);
        }

        // Write the UTF-8 encoded bytes to the LinkedBuffer
        for (int i = 0; i < str.length(); i++) {
            int c = str.charAt(i);
            if (c <= 0x7F) {
                lb.put((byte) c);
            } else if (c <= 0x7FF) {
                lb.put((byte) (0xC0 | (c >> 6)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            } else if (c <= 0xFFFF) {
                lb.put((byte) (0xE0 | (c >> 12)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            } else {
                lb.put((byte) (0xF0 | (c >> 18)));
                lb.put((byte) (0x80 | ((c >> 12) & 0x3F)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (c & 0x3F)));
