private static String performVariableSubstitution(String value, Properties props) {
    int startIndex = -1;
    while ((startIndex = value.indexOf("${", startIndex + 1)) != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex == -1) {
            break; // unmatched "${"
        }

        String placeholder = value.substring(startIndex + 2, endIndex);
        String replacement = props.getProperty(placeholder);
        if (replacement != null) {
            value = value.substring(0, startIndex) + replacement + value.substring(endIndex + 1);
            startIndex = endIndex - replacement.length(); // Adjust index after substitution
        } else {
            startIndex = endIndex; // Move to end index and continue
        }
    }

    return value;
}
