private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int index = 0;
    while (index < value.length()) {
        if (value.charAt(index) == '$' && index + 1 < value.length() && value.charAt(index + 1) == '{') {
            int endIndex = value.indexOf('}', index);
            if (endIndex == -1) {
                break;
            }
            String varName = value.substring(index + 2, endIndex);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
                index = endIndex + 1;
            } else {
                break;
            }
        } else {
            result.append(value.charAt(index));
            index++;
        }
    }
    return result.toString();
