import java.net.URI;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class PathSegmentDecoder {

    /**
     * Decode the path component of a URI as path segments.
     * @param u the URI. If the path component is an absolute path component, then the leading '/' is ignored and is not considered a delimiter of a path segment.
     * @param decode true if the path segments of the path component should be in decoded form.
     * @return the list of path segments.
     */
    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            throw new IllegalArgumentException("URI cannot be null");
        }

        List<String> pathSegments = Arrays.asList(u.getPath().split("/"));
        if (pathSegments.isEmpty()) {
            return new ArrayList<>();
        }

        if (pathSegments.get(0).isEmpty()) {
            pathSegments.remove(0); // remove leading '/'
        }

        return pathSegments.stream()
                .map(segment -> decode ? decodeSegment(segment) : segment)
                .map(PathSegmentImpl::new)
                .collect(Collectors.toList());
    }

    private static String decodeSegment(String segment) {
        try {
            return URI.create("/" + segment).getRawPath().substring(1);
        } catch (URISyntaxException e) {
            return segment; // if decoding fails, return the original segment
        }
    }
}

class PathSegmentImpl {
    private String segment;

    public PathSegmentImpl(String segment) {
        this.segment = segment;
    }

    @Override
    public String toString() {
        return segment;
    }
}
