    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path != null) {
        String[] segments = path.split("/");
        if (segments[0].isEmpty()) {
            segments = new String[segments.length - 1];
            System.arraycopy(segments, 1, segments, 0, segments.length - 1);
        }
        for (String segment : segments) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    // This should not happen with "UTF-8" so we can rethrow the exception as runtime if it does.
                    throw new RuntimeException(e);
                }
            }
            pathSegments.add(PathSegmentImpl.fromString(segment));
        }
    }
    return pathSegments;
