 */
public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("The input box cannot be null.");
    }

    double width = box.getWidth();
    if (width <= 0) {
        throw new IllegalArgumentException("The width of the box must be greater than zero.");
    }

    double halfWidth = width / 2.0;
    double centerX = box.getX() + width / 2.0;
    Box2D box1 = new Box2D(box.getX(), box.getY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(centerX, box.getY(), halfWidth, box.getHeight());

    return new Pair<>(box1, box2);
}
