    while (!found) {
        if (isPrime(prime)) {
            found = true;
        } else {
            prime++;
            if (desiredCapacity >= 1000) {
                double limit = desiredCapacity * 1.11;
                if (prime > limit) {
                    throw new IllegalStateException("No prime within 11% of desired capacity found.");
                }
            }
        }
    }

    return prime;
}

