public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int index = 0;

    while (index < str.length()) {
        char c = str.charAt(index);

        if (c == '\\' && index + 1 < str.length()) {
            char nextChar = str.charAt(index + 1);

            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    // Unknown escape character, just append the backslash and the character
                    sb.append('\\').append(nextChar);
                    break;
            }

            index += 2; // Skip the next character as it's part of the escape sequence
        } else {
            sb.append(c);
            index++;
        }
    }

    return sb.toString();
}
