    /**
     * Converts the given Collection into an array of Strings. The returned array does not contain <code>null</code> entries.
     * Note that {@link Arrays#sort(Object[])} will throw an {@link NullPointerException} if an array element is <code>null</code>.
     * @param collection The collection to convert
     * @return A new array of Strings.
     */
    public static String[] toNoNullStringArray(Collection<?> collection) {
        if (collection == null) {
            throw new IllegalArgumentException("Collection cannot be null");
        }

        Iterator<?> iterator = collection.iterator();
        ArrayList<String> list = new ArrayList<>();

        while (iterator.hasNext()) {
            Object obj = iterator.next();
            if (obj != null) {
                list.add(obj.toString());
            }
        }

        String[] result = list.toArray(new String[0]);
        return result;
    }
}
