    if (utf8Length > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer is too small to hold the UTF-8 string");
    }

    for (int i = 0; i < utf8Length; i++) {
        charBuffer[i] = (char) readU1(classFileBuffer, constantPoolEntryIndex * 4 + 2 + i); // +2 to skip the tag and the length
    }

    return new String(charBuffer, 0, utf8Length);
