private int readU2(byte[] buffer, int offset) {
    return ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
}

private int readU1(byte[] buffer, int offset) {
    return buffer[offset] & 0xFF;
}
