public class ByteVector {
    private byte[] bytes;
    private int size;

    public ByteVector() {
        this.bytes = new byte[16];
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            return this;
        }

        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid byteOffset or byteLength");
        }

        // Ensure the byte vector is large enough
        if (size + byteLength > bytes.length) {
            int newCapacity = Math.max(size + byteLength, size * 2);
            byte[] newBytes = new byte[newCapacity];
            System.arraycopy(bytes, 0, newBytes, 0, size);
            bytes = newBytes;
        }

        System.arraycopy(byteArrayValue, byteOffset, bytes, size, byteLength);
        size += byteLength;

        return this;
    }
}
