import java.util.regex.Pattern;
import java.util.regex.Matcher;

public final class UriMatcher {
    public final MatchResult match(CharSequence uri) {
        // Define the pattern for URI matching
        Pattern pattern = Pattern.compile("^(https?://)?([a-zA-Z0-9.-]+)(:\\d+)?(/.*)?$");

        // Create a matcher for the input URI
        Matcher matcher = pattern.matcher(uri);

        // Check if the URI matches the pattern
        if (matcher.matches()) {
            // If a match is found, return a MatchResult object containing the matched groups
            return new MatchResult(matcher.group(2), matcher.group(3), matcher.group(4));
        } else {
            // If no match is found, return null
            return null;
        }
    }

    // Helper class to hold the match result
    public static class MatchResult {
        private final String hostname;
        private final String port;
        private final String path;

        public MatchResult(String hostname, String port, String path) {
            this.hostname = hostname;
            this.port = port;
            this.path = path;
        }

        public String getHostname() {
            return hostname;
        }

        public String getPort() {
            return port;
        }

        public String getPath() {
            return path;
        }
    }
}
