public class ReflectionRegistry {
    private static Set<Object> registeredObjects = new HashSet<>();

    /**
     * Registers the given object. Used by the reflection methods to avoid infinite loops.
     * @param value The object to register.
     */
    public static synchronized void register(Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }
        if (registeredObjects.contains(value)) {
            return; // Avoid re-registering the same object
        }
        registeredObjects.add(value);
    }
}
