protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = firstEdge.getSource();
    V endVertex = firstEdge.getTarget();

    GraphPath.Builder<V, E> pathBuilder = new GraphPath.Builder<>(graph, startVertex);
    pathBuilder.addEdge(firstEdge);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        if (!edge.getSource().equals(endVertex)) {
            throw new IllegalArgumentException("Edges in the tour must form a continuous path");
        }
        pathBuilder.addEdge(edge);
        endVertex = edge.getTarget();
    }

    return pathBuilder.createPath();
}
