protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return null; // or throw new IllegalArgumentException("Tour set is empty");
    }

    List<EdgePath<V, E>> edgePaths = new ArrayList<>();
    for (E edge : tour) {
        EdgePath<V, E> edgePath = graph.getEdgePath(edge);
        if (edgePath == null) {
            throw new IllegalArgumentException("Edge " + edge + " not found in the graph");
        }
        edgePaths.add(edgePath);
    }

    // Create a single graph path by concatenating the edge paths
    return joinEdgePaths(edgePaths);
}

// Helper method to join a list of edge paths into a single graph path
private <V, E> GraphPath<V, E> joinEdgePaths(List<EdgePath<V, E>> edgePaths) {
    if (edgePaths.isEmpty()) {
        return null; // or throw new IllegalArgumentException("Edge path list is empty");
    }

    V startPoint = edgePaths.get(0).getStartVertex();
    V endPoint = edgePaths.get(edgePaths.size() - 1).getEndVertex();
    List<EdgePath<V, E>> finalPaths = new ArrayList<>();

    for (int i = 0; i < edgePaths.size(); i++) {
        EdgePath<V, E> currentPath = edgePaths.get(i);
        if (i == 0) {
            finalPaths.add(currentPath);
        } else {
            finalPaths.add(new DefaultEdgePath<>(false, currentPath.getStartVertex(), currentPath.getEndVertex(), currentPath.getEdgeReifier()));
        }
    }

    return new DefaultGraphPath<>(graph, false, startPoint, endPoint, finalPaths);
}

