int addConstantNameAndType(final String name, final String descriptor) {
    // Check for null input values
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }

    // Assume constant pool and symbol table are part of the class or at least accessible context
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        if (constantPool.get(i) instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info existingItem = (CONSTANT_NameAndType_info) constantPool.get(i);
            if (existingItem.getName().equals(name) && existingItem.getDescriptor().equals(descriptor)) {
                return i; // Return the index of the existing item
            }
        }
    }

    // If no similar item is found, add a new one
    CONSTANT_NameAndType_info newItem = new CONSTANT_NameAndType_info(name, descriptor);
    constantPool.add(newItem);
    return constantPool.size() - 1; // Return the index of the newly added item
}
