public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the inputs are null or empty
    if (name == null || name.isEmpty() || descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Name and descriptor cannot be null or empty");
    }

    // Check if the constant pool already contains a similar item
    for (Symbol symbol : constantPool) {
        if (symbol.name.equals(name) && symbol.descriptor.equals(descriptor)) {
            return symbol.id;
        }
