private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // Node is the head of the list
        if (next == null) {
            // List has only one node (the head)
            this.head = null;
            this.tail = null;
        } else {
            // List has more than one node
            next.prev = null;
            this.head = next;
        }
    } else {
        prev.next = next;
        if (next == null) {
            // Node is the tail of the list
            this.tail = prev;
        } else {
            // Node is in the middle of the list
            next.prev = prev;
        }
    }

    node.prev = null;
    node.next = null;
    node.value = null;
    return true;
}
