private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long totalSum = 0;

    for (int i = n - 1; i >= 0; i--) {
        if (bounds.get(i) == null) {
            throw new IllegalArgumentException("Input list cannot contain null values");
        }
        totalSum += bounds.get(i);
        suffixSum.add(totalSum);
    }

    // Reverse the suffixSum list to get the correct order
    Collections.reverse(suffixSum);

    return new Pair<>(suffixSum, totalSum);
}
