import java.util.ArrayList;
import java.util.List;

public class SuffixSumCalculator {

    /** 
     * Computes a suffix sum of the bounds. Returns computed suffix sum and the sum of all elements in the bounds list.
     * @param bounds list of integers.
     * @return computed pair of suffix sum list and a sum of all elements.
     */
    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        if (bounds == null || bounds.isEmpty()) {
            return new Pair<>(new ArrayList<>(), 0L);
        }

        int n = bounds.size();
        List<Integer> suffixSum = new ArrayList<>(n);
        long totalSum = 0;

        // Calculate the suffix sum and total sum in one pass
        for (int i = n - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            suffixSum.add(0, totalSum);
        }

        return new Pair<>(suffixSum, totalSum);
    }

    // Simple Pair class implementation for demonstration purposes
    public static class Pair<K, V> {
        private K key;
        private V value;

        public Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }

        public K getKey() {
            return key;
        }

        public V getValue() {
            return value;
        }
    }
}
