    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    // Compute the suffix sum and total sum in reverse order
    for (int i = n - 1, sum = 0; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.set(i, sum);
        totalSum += bounds.get(i);
    }

    return new Pair<>(suffixSum, totalSum);
}
