private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<V,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        int u = graph.getEdgeSource(edge);
        int v = graph.getEdgeTarget(edge);

        List<Pair<Integer,Integer>> localSeparators = new ArrayList<>();

        for (V neighbor : graph.vertexSet()) {
            if (neighbor != u && neighbor != v) {
                if (graph.containsEdge(u, neighbor) && graph.containsEdge(v, neighbor)) {
                    localSeparators.add(Pair.with(Pair.with(u, neighbor), Pair.with(v, neighbor)));
                }
            }
        }

        globalSeparatorList.add(Pair.with(localSeparators, edge));
    }

    return globalSeparatorList;
}
