private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge e : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        // Get the neighborhoods of the vertices of the edge
        Set<Integer> neighborhoodV1 = graph.getNeighborhood(e.getVertex1());
        Set<Integer> neighborhoodV2 = graph.getNeighborhood(e.getVertex2());

        // Find the intersection of the two neighborhoods, which gives the local separators
        for (Integer v : neighborhoodV1) {
            if (neighborhoodV2.contains(v) && !v.equals(e.getVertex1()) && !v.equals(e.getVertex2())) {
                localSeparatorList.add(new Pair<>(v, e));
            }
        }

        // Add the local separator list for the edge to the global separator list
        globalSeparatorList.add(new Pair<>(localSeparatorList, e));
    }

    return globalSeparatorList;
}
