private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E edge : graph.getEdges()) {
        // Get the endpoints of the edge
        Pair<Integer, Integer> endpoints = graph.getEndpoints(edge);
        int u = endpoints.getFirst();
        int v = endpoints.getSecond();

        // Compute the minimal separators in the neighborhood of the edge
        List<List<Integer>> separators = computeMinimalSeparators(graph, u, v);

        // Add the minimal separators and the edge to the global list
        globalSeparatorList.add(new Pair<>(separators, edge));
    }

    return globalSeparatorList;
}

private List<List<Integer>> computeMinimalSeparators(Graph<E> graph, int u, int v) {
    List<List<Integer>> separators = new ArrayList<>();

    // Get the neighbors of u and v
    List<Integer> neighborsU = graph.getNeighbors(u);
    List<Integer> neighborsV = graph.getNeighbors(v);

    // Find the intersection of neighbors
    List<Integer> intersection = new ArrayList<>(neighborsU);
    intersection.retainAll(neighborsV);

    // For each vertex in the intersection, compute the separator
    for (int commonNeighbor : intersection) {
        // Exclude the endpoints and the common neighbor itself
        Set<Integer> separatorSet = new HashSet<>(neighborsU);
        separatorSet.remove(u);
        separatorSet.remove(v);
        separatorSet.remove(commonNeighbor);
        Set<Integer> separatorSetV = new HashSet<>(neighborsV);
        separatorSetV.remove(u);
        separatorSetV.remove(v);
        separatorSetV.remove(commonNeighbor);

        // Combine the sets to form the separator
        separatorSet.addAll(separatorSetV);

        // Convert the set to a list
        List<Integer> separatorList = new ArrayList<>(separatorSet);
        separators.add(separatorList);
    }

    return separators;
}
