public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }

    table.setRowSelectionInterval(row, row);
    int rowHeight = table.getRowHeight();
    int visibleRows = pane.getViewport().getHeight() / rowHeight;
    int firstVisibleRow = pane.getVerticalScrollBar().getValue() / rowHeight;

    if (row < firstVisibleRow || row >= firstVisibleRow + visibleRows) {
        int scrollPosition = row * rowHeight - (visibleRows * rowHeight / 2);
        pane.getVerticalScrollBar().setValue(scrollPosition);
    }

    // Schedule a delayed repaint to ensure the new selection is painted correctly
    SwingUtilities.invokeLater(() -> {
        try {
            Thread.sleep(100); // Delay for 100 milliseconds
            table.repaint();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    });
}
