private static final int MAX_ABBREVIATION_LENGTH = 2;

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("Name start index cannot be negative");
    }
    if (nameStart >= buf.length()) {
        throw new IllegalArgumentException("Name start index out of bounds");
    }

    String name = buf.substring(nameStart);
    if (name.length() <= MAX_ABBREVIATION_LENGTH) {
        buf.append(name);
    } else {
        buf.append(name.charAt(0));
        buf.append(name.length() - 1);
        buf.append(name.charAt(name.length() - 1));
    }
}
