    private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        if (graph == null || vertices == null) {
            throw new IllegalArgumentException("Graph and vertices cannot be null");
        }

        int numVertices = vertices.size();
        if (numVertices <= 1) {
            return true; // A graph with 0 or 1 vertex is trivially a clique
        }

        Set<V> remainingVertices = new HashSet<>(graph.vertexSet());
        remainingVertices.removeAll(vertices);

        for (V vertex : vertices) {
            remainingVertices.remove(vertex);
            if (!remainingVertices.isEmpty()) {
                Set<E> edges = graph.edgesOf(vertex);
                // Check if the vertex is connected to all other vertices in the set
                if (edges.size() != remainingVertices.size()) {
                    return false;
                }
                for (V otherVertex : remainingVertices) {
                    if (!edges.contains(graph.getEdge(vertex, otherVertex))) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
