private void pop(final String descriptor) {
    try {
        if (descriptor == null || descriptor.isEmpty()) {
            throw new IllegalArgumentException("Descriptor cannot be null or empty");
        }

        int count = 0;
        boolean isMethodDescriptor = descriptor.charAt(0) == '(';

        if (isMethodDescriptor) {
            count++;
            for (int i = 1; i < descriptor.length(); i++) {
                char c = descriptor.charAt(i);
                if (c == ')') {
                    break;
                }
                count += getArgumentCount(c);
            }
        } else {
            count = getArgumentCount(descriptor.charAt(0));
        }

        for (int i = 0; i < count; i++) {
            outputFrameStack.pop();
        }
    } catch (EmptyStackException e) {
        throw new IllegalStateException("Attempted to pop from an empty stack", e);
    } catch (Exception e) {
        throw new RuntimeException("Error popping from stack", e);
    }
