private void pop(final String descriptor) {
    // Split the descriptor into individual type descriptors
    String[] types = descriptor.split("(?<=/\\)|\\])\\s*(\\[)?");

    // Iterate over each type descriptor and pop the corresponding number of abstract types from the stack
    for (String type : types) {
        while (type.startsWith("[") || type.equals("V")) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Not enough abstract types on the output frame stack to pop");
            }
            outputFrameStack.pop();
            int arrayDepth = 0;
            while (type.startsWith("[")) {
                arrayDepth++;
                type = type.substring(1);
            }
            if (!type.equals("V")) {
                int width = getAbstractTypeWidth(type);
                if ((outputFrameStack.size() < width) || (arrayDepth > 0 && outputFrameStack.size() < width * arrayDepth)) {
                    throw new IllegalStateException("Not enough abstract types on the output frame stack to pop");
                }
                for (int i = 0; i < width; i++) {
                    outputFrameStack.pop();
                }
                outputFrameStack.add(AbstractType.WIDE);
            }
        }
    }
}

private int getAbstractTypeWidth(String type) {
    switch (type) {
        case "Z":
        case "B":
        case "C":
        case "S":
        case "I":
        case "F":
            return 1;
        case "J":
        case "D":
            return 2;
        case "L":
        case "[":
            return 1;
        default:
            throw new IllegalArgumentException("Invalid type descriptor: " + type);
    }
}
