public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path or relativePath cannot be null");
    }

    // Split the path and relativePath using the standard Java folder separator
    String[] baseParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    // Process the relative path parts
    for (String part : relativeParts) {
        if ("..".equals(part)) {
            // Move up one directory if possible
            if (baseParts.length > 1) {
                baseParts = Arrays.copyOfRange(baseParts, 0, baseParts.length - 1);
            }
        } else if (!"".equals(part)) {
            // Add the part to the base path
            baseParts = Arrays.copyOf(baseParts, baseParts.length + 1);
            baseParts[baseParts.length - 1] = part;
        }
    }

    // Join the parts back into a single path
    return String.join("/", baseParts);
}
