int readTag() throws IOException {
    int b = input.read();
    if (b == -1) {
        return 0; // EOF
    }
    int fieldNumber = (b & 0x7F);
    int wireType = (b >>> 7);
    if ((b & 0x80) == 0) {
        return makeTag(fieldNumber, wireType);
    } else {
        while ((b = input.read()) != -1 && (b & 0x80) != 0) {
            fieldNumber = (fieldNumber << 7) | (b & 0x7F);
        }
        if (b == -1) {
            throw new InvalidProtocolBufferException("Truncated message");
        }
        return makeTag(fieldNumber, wireType);
    }
}

private int makeTag(int fieldNumber, int wireType) {
    if (fieldNumber <= 0 || wireType == WireFormat.WIRETYPE_INVALID_VARINT) {
        throw new InvalidProtocolBufferException("Invalid tag");
    }
    return (fieldNumber << 3) | wireType;
}
